#define NOMINMAX
#include "../RahiTuber/MaxFaceTracker.h"
#include <iostream>
#include <stdexcept>
int main(){MaxFaceTracker tracker;tracker.Start(std::filesystem::absolute("dist/PNGTuberMax").string(),true);if(!tracker.Running())throw std::runtime_error(tracker.status);sf::Clock timeout;while(!tracker.available&&timeout.getElapsedTime().asSeconds()<20){tracker.Poll();sf::sleep(sf::milliseconds(20));}if(!tracker.available)throw std::runtime_error("Bundled helper did not publish a face frame: "+tracker.status);auto image=tracker.textures[0].copyToImage();if(image.getPixel(64,48)!=sf::Color(35,70,100,128))throw std::runtime_error("Live feature pixels changed in the bridge");auto mask=tracker.contours[0].copyToImage();if(mask.getPixel(128,96).r<=128||mask.getPixel(10,10).r>=128)throw std::runtime_error("Tracked contour did not cross the process boundary");if(tracker.pose.lean<=0||tracker.pose.nod<=0||tracker.pose.turn>=0)throw std::runtime_error("Head pose did not cross the process boundary");tracker.Calibrate();tracker.Poll();if(std::abs(tracker.pose.lean)>.001f||std::abs(tracker.pose.nod)>.001f)throw std::runtime_error("Neutral calibration failed");tracker.Stop();if(tracker.Running()||tracker.available||tracker.pose.lean!=0)throw std::runtime_error("Stopping webcam did not clear tracking state");std::cout<<"PASS: bundled helper startup, locked frame transfer, live alpha textures, pose, calibration and shutdown\n";}
